// Monta o system (persona + contexto serializado C7), resolve baseUrl/model/temperature
// por provider e repassa a API key que veio no payload (body.ai.apiKey), resolvida
// server-side pelo Go a partir do banco. O no HTTP usa Authorization Bearer com essa key —
// nao le mais $env/credential; a key crua nunca e logada nem persistida no n8n.
// Providers OpenAI-compatible: gemini + glm(z.ai).
const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const ctx = body.context || {};
// Base URLs default por provider. glm aponta para o endpoint INTERNACIONAL z.ai (a key do
// dono e da z.ai, nao do bigmodel.cn). Config da conta (ai.baseUrl) vence quando preenchida.
const DEFAULT_BASE = {
  gemini: 'https://generativelanguage.googleapis.com/v1beta/openai',
  glm: 'https://api.z.ai/api/paas/v4',
  openai: 'https://api.openai.com/v1',
  deepseek: 'https://api.deepseek.com',
  qwen: 'https://dashscope.aliyuncs.com/compatible-mode/v1',
  kimi: 'https://api.moonshot.cn/v1'
};
const DEFAULT_MODEL = {
  gemini: 'gemini-2.5-flash',
  glm: 'glm-4.6',
  openai: 'gpt-4o-mini',
  deepseek: 'deepseek-chat',
  qwen: 'qwen-plus',
  kimi: 'moonshot-v1-8k'
};
// Nome da env por provider — mantido so como referencia/diagnostico; a key real vem no payload.
const KEY_ENV = {
  gemini: 'CALENDAR_GEMINI_API_KEY',
  glm: 'CALENDAR_ZAI_API_KEY'
};
const provider = String(ai.provider || 'gemini').toLowerCase();
// A API key vem no payload (body.ai.apiKey), resolvida server-side pelo Go a partir do banco.
const apiKey = String(ai.apiKey || '');
// Se o modelo salvo na config nao bate com o provider (ex.: sobrou claude-sonnet-5 ao
// trocar pra Gemini), cai no default do provider — evita 404 de modelo inexistente.
const PREFIX = { gemini: 'gemini', glm: 'glm' };
let model = ai.model || DEFAULT_MODEL[provider] || 'gemini-2.5-flash';
if (PREFIX[provider] && String(model).toLowerCase().indexOf(PREFIX[provider]) !== 0) { model = DEFAULT_MODEL[provider] || model; }
const baseUrl = String(ai.baseUrl || DEFAULT_BASE[provider] || '').replace(/\/+$/, '');
const keyEnv = KEY_ENV[provider] || 'CALENDAR_GEMINI_API_KEY';
let temperature = Number(ai.temperature);
if (isNaN(temperature)) temperature = 0.7;
if (temperature < 0) temperature = 0;
if (temperature > 1) temperature = 1;
const DEFAULT_SYSTEM = [
  'Voce e um assistente de estrategia de conteudo de uma agencia brasileira.',
  'Use o contexto do cliente e do mes fornecido abaixo para responder de forma direta e pratica, em pt-BR.',
  'Nao invente dados que nao estejam no contexto; quando faltar, diga o que falta de forma objetiva.'
].join(String.fromCharCode(10));
const baseSystem = (ai.systemPrompt && String(ai.systemPrompt).trim()) ? String(ai.systemPrompt) : DEFAULT_SYSTEM;
const NL = String.fromCharCode(10);
let cx = NL + NL + '=== CONTEXTO ===' + NL;
cx += 'Mes em foco: ' + (ctx.month || '(mes corrente)') + NL;
const client = ctx.client || null;
if (client && (client.id || client.name)) {
  cx += NL + 'Cliente em foco: ' + (client.name || '') + ' (id: ' + (client.id || '') + ')' + NL;
  cx += 'Perfil do cliente: ' + JSON.stringify(client.profile || {}) + NL;
} else {
  cx += NL + 'Nenhum cliente filtrado (visao geral da agencia).' + NL;
}
const holidays = Array.isArray(ctx.holidays) ? ctx.holidays : [];
if (holidays.length) {
  cx += NL + 'Datas comemorativas / feriados do mes:' + NL;
  for (const h of holidays) {
    cx += '- ' + (h.date || '') + ': ' + (h.name || '') + ' (' + (h.set || '') + ')' + NL;
  }
} else {
  cx += NL + 'Sem feriados cadastrados para este mes.' + NL;
}
const events = Array.isArray(ctx.events) ? ctx.events : [];
if (events.length) {
  cx += NL + 'Eventos ja agendados no mes:' + NL;
  for (const e of events) {
    cx += '- ' + (e.date || '') + ' [' + (e.type || '') + '] ' + (e.title || '') + ' (status: ' + (e.status || '') + ')' + NL;
  }
} else {
  cx += NL + 'Nenhum evento agendado no mes.' + NL;
}
const monthNotes = ctx.monthNotes || '';
if (monthNotes) {
  cx += NL + 'Notas do mes (HTML, use como contexto):' + NL + monthNotes + NL;
}
const plans = Array.isArray(ctx.plans) ? ctx.plans : [];
if (plans.length) {
  cx += NL + 'Planos estrategicos gerados (resumo):' + NL;
  for (const p of plans) {
    cx += '- plano ' + (p.id || '') + ' mes ' + (p.month || '') + ' status ' + (p.status || '') + ' (' + (p.provider || '') + '/' + (p.model || '') + ')' + NL;
  }
}
const ENVELOPE_RULE = NL + NL + 'INSTRUCAO FINAL (vale MAIS que tudo acima, inclusive a de responder em texto): responda SEMPRE com UM objeto JSON plano, nada fora dele, sem crase nem markdown:' + NL +
  '{"answer":"sua resposta em pt-BR","create":"none"}' + NL +
  '- create: "none" = conversa normal; "event" = criar um evento no calendario; "task" = criar uma tarefa.' + NL +
  '- Quando create for "event" ou "task", inclua NO MESMO objeto (mesmo nivel): title, date (YYYY-MM-DD), time (HH:MM), type, status, clientId. Para task use dueDate no lugar de date.' + NL +
  '- Se o usuario pedir para criar/agendar/marcar/adicionar algo, create NUNCA pode ser "none".' + NL +
  '- clientId = id do cliente em foco do CONTEXTO quando houver, senao "" (nunca invente). status padrao "planejado". Use o mes em foco para datas relativas.' + NL +
  'Exemplo: usuario "cria uma gravacao pra Perola dia 10 de julho" vira {"answer":"Vou propor uma gravacao da Perola em 10/07.","create":"event","title":"Gravacao Perola","date":"2026-07-10","time":"09:00","type":"gravacao","status":"planejado","clientId":""}';
const system = baseSystem + cx + ENVELOPE_RULE;
const question = String(body.question || '').trim();
// Historico da conversa: vem do payload (body.history), persistido no banco pelo Go.
// O n8n NAO guarda memoria; so repassa o que o back mandou. Sanitiza cada item
// (so role user/assistant com content) e monta a array de messages do LLM na ordem
// system+context, depois o historico, depois a pergunta atual.
const historyIn = Array.isArray(body.history) ? body.history : [];
const history = [];
for (const h of historyIn) {
  if (!h || typeof h !== 'object') continue;
  const role = String(h.role || '');
  const content = String(h.content || '');
  if ((role === 'user' || role === 'assistant') && content) { history.push({ role: role, content: content }); }
}
const messages = [{ role: 'system', content: system }];
for (const h of history) { messages.push(h); }
messages.push({ role: 'user', content: question });
return [{ json: {
  provider: provider,
  model: model,
  baseUrl: baseUrl,
  keyEnv: keyEnv,
  apiKey: apiKey,
  temperature: temperature,
  system: system,
  question: question,
  messages: messages
} }];

// Normaliza a resposta OpenAI-compatible (choices[0].message.content) para { answer }.
// Erro do HTTP node (apos retryOnFail): mensagem LIMPA por tipo, sem JSON cru na tela.
let r = $input.first().json || {};
if (Array.isArray(r)) r = r[0] || {};
if (r.error) {
  const raw = String((r.error && (r.error.message || r.error.description)) || '');
  const low = raw.toLowerCase();
  let friendly;
  if (low.indexOf('503') >= 0 || low.indexOf('unavailable') >= 0 || low.indexOf('overload') >= 0 || low.indexOf('high demand') >= 0) {
    friendly = 'O provedor de IA esta sobrecarregado agora (limite temporario do modelo). Tente de novo em instantes.';
  } else if (low.indexOf('429') >= 0 || low.indexOf('quota') >= 0 || low.indexOf('rate') >= 0 || low.indexOf('exceeded') >= 0) {
    friendly = 'Limite de uso do provedor de IA atingido (cota). Tente mais tarde ou troque de modelo/provedor na aba IA.';
  } else if (low.indexOf('401') >= 0 || low.indexOf('403') >= 0 || low.indexOf('api key') >= 0 || low.indexOf('unauthorized') >= 0) {
    friendly = 'A chave de API do provedor foi recusada. Confira a chave na aba IA.';
  } else {
    let detail = '';
    const m = raw.match(/"message"\s*:\s*"([^"]+)"/);
    if (m) detail = m[1];
    friendly = detail ? ('Nao consegui falar com a IA: ' + detail) : 'Nao consegui falar com a IA agora. Tente de novo.';
  }
  return [{ json: { answer: friendly, aiError: true } }];
}
// WAVE 5 (E7): o LLM responde SEMPRE num JSON PLANO {answer, create, ...campos} (json mode).
// Monta a proposal a partir dos campos planos; create='none'/ausente = conversa normal.
const choices = Array.isArray(r.choices) ? r.choices : [];
const msg = (choices[0] && choices[0].message && choices[0].message.content) || '';
if (!msg) {
  return [{ json: { answer: 'A IA respondeu vazio. Verifique o modelo/base URL do provider na aba IA.', aiError: true } }];
}
function parseEnvelope(text) {
  let s = String(text).trim();
  const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) s = fence[1].trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
const env = parseEnvelope(msg);
if (!env || typeof env !== 'object') {
  return [{ json: { answer: String(msg) } }];
}
const answer = String(env.answer == null ? '' : env.answer) || String(msg);
const create = String(env.create || 'none').toLowerCase();
if (create === 'event' || create === 'task') {
  const fields = {
    title: String(env.title || ''),
    date: String(env.date || ''),
    time: String(env.time || ''),
    type: String(env.type || ''),
    status: String(env.status || ''),
    dueDate: String(env.dueDate || env.date || ''),
    columnId: String(env.columnId || ''),
    clientId: String(env.clientId || '')
  };
  if (fields.title) {
    return [{ json: { answer: answer, proposal: { kind: create, fields: fields } } }];
  }
}
return [{ json: { answer: answer } }];
